public int findLargestSubstring(List<String> strings) {
        String longestStr = "";
        for (String str : strings) {
            if (str.length() > longestStr.length()) {
                longestStr = str;
            }
        }

        for (int i = longestStr.length(); i > 0; i--) {
            for (int j = 0; j <= longestStr.length() - i; j++) {
                String substring = longestStr.substring(j, j + i);
                String reversed = new StringBuilder(substring).reverse().toString();
                for (String str : strings) {
                    if (str.contains(substring) || str.contains(reversed)) {
                        return i;
                    }
                }
            }
        }

        return 0;
    }

