public double trimMean(int[] arr) {
    int len = arr.length;
    Arrays.sort(arr);
    int start = (int) (0.05 * len);
    int end = len - (int) (0.05 * len);
    int sum = 0;
    for (int i = start; i < end; i++) {
        sum += arr[i];
    }
    return sum * 1.0 / (end - start);
}

