public boolean canArrange(int[] arr, int k) {
        int n = arr.length;
        if (n % 2 != 0) {
            return false; // If the array length is odd, it is not possible to divide into pairs
        }

        Map<Integer, Integer> countMap = new HashMap<>();
        for (int num : arr) {
            int remainder = num % k;
            countMap.put(remainder, countMap.getOrDefault(remainder, 0) + 1);
        }

        boolean canFormPairs = true;
        for (int remainder = 0; remainder < k; remainder++) {
            if (remainder % 2 == 0) {
                if (countMap.getOrDefault(remainder, 0) != countMap.getOrDefault(k - remainder, 0)) {
                    canFormPairs = false;
                    break;
                }
            } else {
                if (countMap.containsKey(remainder) && countMap.containsKey(k - remainder)) {
                    canFormPairs = false;
                    break;
                }
            }
        }

        return canFormPairs;
    }

