public String sortString(String s) {
        if (s == null || s.length() <= 1) {
            return s;
        }

        Deque<Character> maxQueue = new PriorityQueue<>((a, b) -> b - a);
        Deque<Character> minQueue = new PriorityQueue<>();
        boolean[] seen = new boolean[256];

        for (char c : s.toCharArray()) {
            if (seen[c]) {
                maxQueue.offer(c);
                minQueue.offer(c);
            } else {
                seen[c] = true;
            }
        }

        String result = new StringBuilder();

        while (!maxQueue.isEmpty() || !minQueue.isEmpty()) {
            // Append the smaller character to the result and remove from the queue
            if (!maxQueue.isEmpty() && (!minQueue.isEmpty() || maxQueue.peek() >= minQueue.peek())) {
                char top = maxQueue.poll();
                result.append(top);
                seen[top] = false;
            }

            // Append the larger character to the result and remove from the queue
            if (!minQueue.isEmpty()) {
                char top = minQueue.poll();
                result.append(top);
                seen[top] = false;
            }
        }

        return result.toString();
    }

