public String sortString(String s) {
        PriorityQueue<char[]> queue = new PriorityQueue<>((a, b) -> {
            if (a[0] == b[0]) return Integer.compare(a[1], b[1]);
            return Character.compare(a[0], b[0]);
        });

        Map<char[], Integer> charCountMap = new HashMap<>();

        for (char c : s.toCharArray()) {
            charCountMap.put(new char[] { c, c }, charCountMap.getOrDefault(new char[] { c, c }, 0) + 1);
            queue.add(new char[] { c, c });
        }

        StringBuilder result = new StringBuilder();

        while (!queue.isEmpty()) {
            char[] smallest = queue.remove();
            int count = charCountMap.getOrDefault(smallest, 0);

            if (count > 0) {
                result.append(smallest[0]);
                charCountMap.put(smallest, count - 1);
            }

            char[] largest = queue.poll();
            int maxCount = charCountMap.getOrDefault(largest, 0);

            if (maxCount > 0) {
                result.append(largest[0]);
                charCountMap.put(largest, maxCount - 1);
            }
        }

        return result.toString();
    }

