public boolean splitArraySameAverage(int[] nums) {
    // Calculate the total sum of the array
    int totalSum = Arrays.stream(nums).sum();

    // If the total sum is odd, it's impossible to split the array into two equal averages
    if (totalSum % 2 != 0) {
        return false;
    }

    // Calculate the target sum for one of the partitions
    int targetSum = totalSum / 2;

    // Check if there exists a prefix sum that equals the target sum
    int prefixSum = 0;
    for (int num : nums) {
        prefixSum += num;
        if (prefixSum == targetSum) {
            return true;
        }
    }

    return false;
}

