    boolean[] binaryDigits = new boolean[2 << k];

    for (int i = 0; i <= s.length() - k; i++) {
        byte b = (byte) Integer.parseInt(s.substring(i, i + k), 2);
        binaryDigits[b] = true;
    }

    return Arrays.stream(binaryDigits).allMatch(b -> b);
}

