    // Create a list of Fibonacci numbers up to k
    List<Integer> fibNumbers = new ArrayList<>();
    int a = 1, b = 1;
    while (a <= k) {
        fibNumbers.add(a);
        int next = a + b;
        a = b;
        b = next;
    }

