public int findMinFibonacciNumbers(int k) {
    // Base cases
    if (k == 0) return 0;
    if (k <= 2) return 1;

    int[] fib = {1, 1};
    int i = 2;
    while (fib[i] <= k) {
        fib[i + 1] = fib[i] + fib[i - 1];
        i++;
    }

    int count = 0;
    int j = i - 1;
    while (j >= 0 && k > 0) {
        while (k >= fib[j]) {
            k -= fib[j];
            count++;
        }
        j--;
    }

    return count;
}

