public static int singleNumber(int[] nums) {
    int result = 0;

    // Iterate through each bit position (0 to 31)
    for (int i = 0; i < 32; i++) {
        int countOnes = 0;

        // Check each number if the current bit is set to 1
        for (int num : nums) {
            if ((num & (1 << i)) != 0) {
                countOnes++;
            }
        }

        // If the count of 1s in the current bit is not divisible by 3, set the bit in result
        if (countOnes % 3 != 0) {
            result |= (1 << i);
        }
    }

    return result;
}

