public static int countDigitOne(int n) {
    if (n == 0) return 0;
    int count = 0;
    int power = 1;
    while (n / power >= 1) {
        // Determine the number of times 1 appears in the current position
        int currDigit = n / power % 10;
        int beyond = n / (power * 10);

        // Count 1s in digits 0 to beyond
        count += beyond * power;

        // If currDigit is 1, count the additional 1s in the current position
        if (currDigit == 1) {
            count += n - beyond * power + 1;
        } else if (currDigit > 1) {
            count += power;
        }

        power *= 10;
    }
    return count;
}

