public static int countDigitOne(int n) {
    if (n < 1) {
        return 0;
    }

    int[] counts = new int[10];
    for (int i = 1; i <= n; i++) {
        // Get the rightmost digit
        int rightmost = i % 10;

        // Count the rightmost digit 1s
        if (rightmost == 1) {
            counts[1]++;
        }

        if (i >= 10) {
            // Count the number of times 1 appears in the tens place
            counts[(i / 10) % 10]++;
            // Count the number of times 1 appears in the hundred place (and so on)
            for (int j = 1; j <= (i / 10) % 10; j++) {
                counts[j]++;
            }
        }
    }

    // Sum the counts of 1s in all place values
    return Arrays.stream(counts).sum();
}

