public static int squarePermutations(int[] A) {
    long count = 0;
    int n = A.length;
    Set<int[]> seen = new HashSet<>();

    // Helper function to check if a number is a perfect square
    boolean isPerfectSquare(int x) {
        int s = (int) Math.sqrt(x);
        return s * s == x;
    }

    // Depth-First Search (DFS) to find valid permutations
    void dfs(int[] A, int p) {
        if (p == n) {
            seen.add(ArrayUtils.clone(A));
            count++;
            return;
        }

        for (int i = p; i < n; i++) {
            if (i > p && A[i] == A[p]) continue; // Skip duplicates
            swap(A, p, i);
            if (isPerfectSquare(A[p] * A[p + 1])) {
                dfs(A, p + 1);
            }
            swap(A, p, i); // backtrack
        }
    }

    // Swap two elements in the array
    void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

