public static int squarePermutations(int[] A) {
    int[] squares = new int[] {0, 1, 4, 9, 16, 25, 36, 49, 64, 81};
    int N = A.length;
    int[] dp = new int[N + 1];
    Arrays.fill(dp, 0);

    // Base case: There is exactly one permutation for an empty array
    dp[0] = 1;

    for (int i = 1; i <= N; i++) {
        int sum = A[i - 1] + A[i - 2];
        if (sum >= 0 && sum <= 20) {
            dp[i] = dp[i - 1];
            for (int j = squares[(int) Math.sqrt(sum)]; j >= 0; j--) {
                dp[i] += dp[j];
            }
        }
    }

    return dp[N];
}

