        return -1;
    }

    int remaining = n;
    int smallest = n;

    // Sort the digits of n in ascending order to find the smallest candidate
    while (remaining != 0) {
        int digit = remaining % 10;
        if (digit > smallest % 10) {
            smallest = digit;
        }
        remaining /= 10;
    }

    // If the smallest digit is not the lowest digit, try to place a smaller digit in the sorted smallest position
    int smallestIndex = 0;
    for (int i = 1; i < String.valueOf(smallest).length(); i++) {
