public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        if (n == 0) return result;
        int base = 10;
        int num = 1;
        while (true) {
            while (num <= n) {
                result.add(num);
                num += base;
            }
            int tens = num / base;
            num -= tens * base;
            while (num > tens) {
                num -= 1;
                result.add(num);
            }
            base *= 10;
            if (num > n-base*10) {
                return result;
            }
        }
    }

